--liquibase formatted sql

--changeset fit-team:012-seed-real-luxury-subcategories-data
--comment Seed 520 REAL luxury products (20 items for each of the 26 subcategories) with unique titles, descriptions, slugs & prices

-- 1. Seed Images
ON CONFLICT (id) DO NOTHING;

-- 2. Seed Products (520 Real Luxury Items)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description;

-- 3. Seed Product Categories
ON CONFLICT DO NOTHING;

-- 4. Seed Product Details
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, quantity = EXCLUDED.quantity;

-- 5. Seed Product Images
ON CONFLICT DO NOTHING;
